cards.solution:
const API = "https://api.toko.contoh";
async function tambahProduk(produk) {
  const res = await fetch(API + "/products", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(produk),
  });
  const data = await res.json();
  if (res.ok) console.log(res.status, data.id, data.name);
  else console.log(res.status, data.error);
}
await tambahProduk({ name: "Es Jeruk", price: 10000 });
await tambahProduk({ name: "", price: 5000 });
